const CHEM_QUESTIONS = [];
const CHEM_UNIT_COUNTS = {};
function chemQuestion(unit, topicCode, topic, skill, stem, correct, distractors, why, variantGroupId, stimulusGroupId, stimulus) {
  const number = (CHEM_UNIT_COUNTS[unit] || 0) + 1;
  CHEM_UNIT_COUNTS[unit] = number;
  const correctIndex = CHEM_QUESTIONS.length % 4;
  const options = distractors.slice();
  options.splice(correctIndex, 0, correct);
  const explanation = why.length >= 90 ? why : `${why} This reasoning connects the observed or calculated result directly to the chemical model in the question.`;
  CHEM_QUESTIONS.push({
    id: `apchem-${unit.toLowerCase()}-${String(number).padStart(3, "0")}`,
    unit, topicCode, topic, skill, type: "s", q: stem, o: options, c: [correctIndex], e: explanation,
    ...(variantGroupId ? { variantGroupId } : {}),
    ...(stimulusGroupId ? { stimulusGroupId } : {}),
    ...(stimulus ? { stimulus } : {}),
  });
}
{
const q = chemQuestion;

// Unit 1 — Atomic Structure and Properties
q("U1","1.1","Moles and Molar Mass","5.A","A 9.00 g sample of water contains approximately how many moles of H2O?","0.500 mol",["0.250 mol","1.00 mol","18.0 mol"],"Dividing the sample mass by water's molar mass, about 18.0 g mol⁻¹, gives 9.00/18.0 = 0.500 mol. Moles measure amount of substance, not the number of grams or molecules directly.","chem-1.1-moles");
q("U1","1.1","Moles and Molar Mass","5.B","Which expression gives the number of molecules in 0.250 mol of CO2?","(0.250)(6.022×10^23)",["0.250/6.022×10^23","(44.0)(6.022×10^23)","44.0/0.250"],"Avogadro's constant converts moles to representative particles, so 0.250 mol must be multiplied by 6.022×10²³ molecules per mole. The molar mass is unnecessary once the amount is already in moles.","chem-1.1-moles");
q("U1","1.2","Mass Spectra of Elements","4.B","An element has two isotopes at mass numbers 35 and 37. Its mass spectrum shows the mass-35 peak is about three times as intense as the mass-37 peak. Which average atomic mass is most reasonable?","About 35.5 u",["Exactly 35.0 u","About 36.0 u","About 36.5 u"],"A roughly 3:1 abundance places the weighted mean one quarter of the way from 35 to 37: 35 + 0.25(2) ≈ 35.5 u. The mean must be closer to the more abundant mass-35 isotope.","chem-1.2-spectrum");
q("U1","1.2","Mass Spectra of Elements","5.C","A mass spectrum has isotope peaks at 10 u (20.0%) and 11 u (80.0%). What is the element's average atomic mass?","10.8 u",["10.2 u","10.5 u","11.0 u"],"The weighted average is (10)(0.200) + (11)(0.800) = 10.8 u. Averaging the two masses without weighting would ignore the much greater abundance of the 11 u isotope.","chem-1.2-spectrum");
q("U1","1.3","Elemental Composition of Pure Substances","5.A","A compound is 40.0% carbon, 6.7% hydrogen, and 53.3% oxygen by mass. Which empirical formula is consistent with these percentages?","CH2O",["CHO","C2H2O","CH4O"],"For a 100 g sample, the mole amounts are about 3.33 mol C, 6.65 mol H, and 3.33 mol O. Dividing by the smallest produces the 1:2:1 whole-number ratio CH₂O.","chem-1.3-empirical");
q("U1","1.3","Elemental Composition of Pure Substances","5.D","A pure oxide contains 2.00 mol of metal atoms and 3.00 mol of oxygen atoms. What is its empirical formula if the metal is represented by M?","M2O3",["MO","MO2","M3O2"],"The empirical formula uses the simplest whole-number atom ratio. A 2.00:3.00 mole ratio of metal to oxygen is already 2:3, so the formula is M₂O₃.","chem-1.3-empirical");
q("U1","1.4","Composition of Mixtures","5.A","A 10.0 g mixture contains only NaCl and sand. After dissolving and separating the NaCl, 3.5 g of dry sand remains. What mass percent of NaCl was in the original mixture?","65%",["35%","54%","74%"],"The NaCl mass was 10.0 − 3.5 = 6.5 g. Dividing 6.5 g by the original 10.0 g mixture and multiplying by 100 gives 65% NaCl by mass.","chem-1.4-mixture");
q("U1","1.4","Composition of Mixtures","4.C","Two samples of the same homogeneous salt solution are taken after thorough mixing. Which statement is expected to be true?","Both samples have the same solute mass fraction.",["The smaller sample has a lower solute mass fraction.","The denser sample contains only solvent.","The samples must contain equal masses of solute."],"A homogeneous solution has uniform composition throughout, so representative portions have the same solute-to-solution mass ratio even when the portions have different total masses.","chem-1.4-mixture");
q("U1","1.5","Atomic Structure and Electron Configuration","1.A","Which electron configuration represents a neutral sodium atom in its ground state?","1s2 2s2 2p6 3s1",["1s2 2s2 2p5 3s2","1s2 2s2 2p6","1s2 2s2 2p6 3s2"],"Neutral sodium has 11 electrons. Filling orbitals in increasing energy gives 1s² 2s² 2p⁶ 3s¹, with the final valence electron occupying the 3s subshell.","chem-1.5-config");
q("U1","1.5","Atomic Structure and Electron Configuration","4.A","Which species has the electron configuration 1s2 2s2 2p6?","Na+",["Na","Mg","F"],"Na⁺ has lost sodium's single 3s valence electron and therefore has 10 electrons, matching 1s²2s²2p⁶. Neutral Na has 11 electrons, Mg has 12, and F has 9.","chem-1.5-config");
q("U1","1.6","Photoelectron Spectroscopy","4.B","In a photoelectron spectrum, electrons in which peak require the greatest photon energy to remove?","The peak with the greatest binding energy",["The peak with the lowest binding energy","The least intense peak in every spectrum","The peak corresponding to the outermost occupied shell"],"Binding energy is the energy required to remove an electron. A larger binding-energy value therefore means a more energetic photon is needed to eject those electrons from the atom.","chem-1.6-pes");
q("U1","1.6","Photoelectron Spectroscopy","6.B","A PES spectrum of element X has a valence peak twice the intensity of the corresponding valence peak for element Y, while both peaks occur at similar binding energy. Which inference is best supported?","X has about twice as many electrons in that subshell as Y.",["X has twice the nuclear charge of Y.","X's valence electrons have twice the binding energy.","Y necessarily has twice as many occupied shells."],"Within comparable PES measurements, peak intensity reflects the relative number of electrons in the subshell, whereas the horizontal position reflects their binding energy. Similar positions do not imply equal occupancy.","chem-1.6-pes");
q("U1","1.7","Periodic Trends","4.D","Why is the first ionization energy of Na lower than that of Mg?","Na's outer electron experiences a lower effective nuclear attraction and is removed from a filled-shell core more easily.",["Na has more protons than Mg.","Mg's valence electron is in a higher principal energy level.","Na has a smaller atomic radius than Mg."],"Across period 3, effective nuclear charge generally increases while valence electrons remain in the same principal shell. Mg therefore holds its 3s electrons more strongly than Na holds its lone 3s electron.","chem-1.7-trends");
q("U1","1.7","Periodic Trends","6.C","Which comparison is correct for the isoelectronic ions O2− and F−?","F− has the smaller radius because its 10 electrons are attracted by more protons.",["O2− has the smaller radius because it has the larger negative charge.","The ions have identical radii because they have equal electron counts.","F− has the larger radius because fluorine is farther right in the period."],"Both ions contain 10 electrons, so the principal difference is nuclear charge. Fluorine has nine protons versus oxygen's eight, producing stronger attraction and a smaller electron cloud for F⁻.","chem-1.7-trends");
q("U1","1.8","Valence Electrons and Ionic Compounds","1.B","Which formula is expected when Mg2+ combines with N3− to form a neutral ionic compound?","Mg3N2",["MgN","Mg2N3","MgN2"],"Charge neutrality requires equal total positive and negative charge. Three Mg²⁺ ions provide +6 and two N³⁻ ions provide −6, giving the simplest neutral formula Mg₃N₂.","chem-1.8-ionic");
q("U1","1.8","Valence Electrons and Ionic Compounds","4.A","Which representation best describes solid NaCl at the particle level?","A repeating three-dimensional lattice of alternating Na+ and Cl− ions",["Discrete NaCl molecules separated by empty space","Neutral Na atoms mixed randomly with Cl2 molecules","Parallel chains joined by covalent Na—Cl bonds only"],"An ionic solid is an extended electrostatic lattice rather than a collection of discrete molecules. Oppositely charged Na⁺ and Cl⁻ ions occupy repeating positions that maximize attractions and limit repulsions.","chem-1.8-ionic");

// Unit 2 — Compound Structure and Properties
q("U2","2.1","Types of Chemical Bonds","4.D","The bond in HCl is polar covalent primarily because","Cl attracts the shared bonding electrons more strongly than H does",["the electrons are transferred completely from H to Cl","H and Cl have identical electronegativities","both atoms contribute two electrons to the bond"],"A polar covalent bond results from unequal sharing caused by an electronegativity difference. Chlorine's stronger attraction shifts electron density toward Cl without complete electron transfer.","chem-2.1-bonds");
q("U2","2.1","Types of Chemical Bonds","6.A","Which observation most strongly supports classifying a solid as ionic rather than molecular?","It does not conduct as a solid but conducts when molten.",["It has a low boiling point and is volatile.","It dissolves in hexane but not in water.","It is soft and melts near room temperature."],"In an ionic solid the charged particles are fixed in a lattice, but melting frees the ions to move and carry current. Molecular substances generally do not create mobile ions simply by melting.","chem-2.1-bonds");
q("U2","2.2","Intramolecular Force and Potential Energy","4.B","As two H atoms approach from very large separation, the potential energy first decreases and then rises steeply at very short distance. The minimum corresponds to","the equilibrium bond length where attractive and repulsive effects balance",["complete removal of both electrons","the distance at which no forces act anywhere in the molecule","an unstable maximum-energy arrangement"],"The bond length is associated with the minimum of the internuclear potential-energy curve. At that separation, attraction lowers energy but further compression causes strong nucleus-nucleus and electron-electron repulsion.","chem-2.2-potential");
q("U2","2.2","Intramolecular Force and Potential Energy","6.C","Compared with a weaker bond between the same kinds of atoms, a stronger bond generally has","a deeper potential-energy well and requires more energy to break",["a shallower well and less energy to break","zero attractive interaction at its equilibrium distance","a positive potential energy at all separations"],"Bond dissociation requires climbing from the potential-energy minimum toward the separated-atom limit. A deeper minimum therefore corresponds to a larger bond energy and a stronger bond.","chem-2.2-potential");
q("U2","2.3","Structure of Ionic Solids","1.B","Why are ionic crystals often brittle when struck?","A shift can bring like-charged ion layers adjacent, producing strong repulsion and fracture.",["The impact converts all ionic bonds into metallic bonds.","Ions become neutral atoms and evaporate from the lattice.","The crystal contains weak intermolecular forces between discrete molecules."],"Ionic lattices depend on an ordered alternation of opposite charges. Mechanical displacement can align ions of the same charge, and the resulting electrostatic repulsion cleaves the crystal rather than allowing layers to slide.","chem-2.3-ionic-solid");
q("U2","2.3","Structure of Ionic Solids","4.A","Which change would most likely increase the magnitude of lattice attraction in a series of similarly structured ionic compounds?","Increasing ionic charges while keeping ion sizes comparable",["Decreasing ionic charges while decreasing polarity","Replacing ions with neutral molecules","Increasing the distance between oppositely charged ions"],"Coulombic attraction grows with the product of ionic charges and decreases with separation. Larger charge magnitudes therefore strengthen lattice attractions when ion size and structure are otherwise similar.","chem-2.3-ionic-solid");
q("U2","2.4","Structure of Metals and Alloys","1.B","The electrical conductivity of a metal is best explained by","delocalized valence electrons that can move through the metal lattice",["mobile positive metal nuclei flowing through fixed electrons","transfer of electrons between isolated metal molecules","hydrogen bonding among neighboring metal atoms"],"Metallic bonding leaves valence electrons delocalized over many nuclei. Because these electrons are mobile, an applied electric field can produce charge flow through the solid lattice.","chem-2.4-metals");
q("U2","2.4","Structure of Metals and Alloys","6.A","An alloy is harder than the pure metal from which it is made. Which particle-level explanation is most plausible?","Different-sized atoms disrupt regular layers and make dislocation or layer motion more difficult.",["Alloying removes all valence electrons from the solid.","The added atoms convert metallic bonding entirely to hydrogen bonding.","The alloy becomes a collection of isolated gas-phase atoms."],"Metal deformation depends on movement of layers and dislocations. Substitutional or interstitial atoms of different size distort the lattice and can hinder that motion, increasing hardness.","chem-2.4-metals");
q("U2","2.5","Lewis Diagrams","1.A","How many lone pairs are shown on the central O atom in the usual Lewis structure of H2O?","2",["0","1","3"],"Oxygen has six valence electrons and forms two single O—H bonds. Four electrons remain nonbonding on oxygen, which are represented as two lone pairs in the Lewis structure.","chem-2.5-lewis");
q("U2","2.5","Lewis Diagrams","4.A","Which Lewis structure feature is required for CO2 in its lowest-formal-charge representation?","Two C=O double bonds with carbon in the center",["One C—O single bond and one unbonded O atom","Three C—O single bonds around carbon","A lone pair on carbon and no bonds to oxygen"],"With carbon central, two C=O double bonds give carbon and both oxygens complete octets while assigning formal charge zero to each atom. Alternative single-bond patterns create unnecessary formal charges.","chem-2.5-lewis");
q("U2","2.6","Resonance and Formal Charge","4.C","In nitrate, NO3−, three equivalent N—O bond lengths are observed. This is best explained by","resonance delocalization that makes the actual bonds equivalent averages",["rapid rotation that converts N atoms into O atoms","three permanently different bond orders measured at different times","complete absence of electron sharing between N and O"],"Equivalent nitrate bond lengths are consistent with a resonance hybrid in which π electron density is delocalized over the three N—O connections rather than confined to one fixed double bond.","chem-2.6-resonance");
q("U2","2.6","Resonance and Formal Charge","5.A","Using formal charge = valence electrons − nonbonding electrons − 1/2(bonding electrons), what is the formal charge on O in a structure where O has three lone pairs and one single bond?","−1",["0","+1","−2"],"Oxygen contributes 6 valence electrons. With 6 nonbonding electrons and half of the 2 bonding electrons, formal charge = 6 − 6 − 1 = −1.","chem-2.6-resonance");
q("U2","2.7","VSEPR and Hybridization","1.A","What molecular geometry is predicted for CH4?","Tetrahedral",["Trigonal planar","Bent","Linear"],"Four bonding electron domains surround carbon and there are no lone pairs on the central atom. VSEPR places those domains as far apart as possible in a tetrahedral arrangement.","chem-2.7-vsepr");
q("U2","2.7","VSEPR and Hybridization","4.D","The carbon atoms in ethene, C2H4, are commonly described as sp2 hybridized because each carbon has","three regions of sigma bonding/electron density arranged approximately trigonal planar",["two electron domains arranged linearly and no pi bond","four equivalent sigma-bond directions in a tetrahedral arrangement","one electron domain and three lone pairs"],"Each carbon in ethene forms three sigma-bonding domains and retains an unhybridized p orbital for the π bond. Three domains correspond to sp² hybridization and trigonal-planar local geometry.","chem-2.7-vsepr");

// Unit 3 — Properties of Substances and Mixtures
q("U3","3.1","Intermolecular and Interparticle Forces","4.D","Why does water have a higher boiling point than H2S despite H2S having the larger molar mass?","Water molecules form extensive hydrogen-bonding interactions.",["Water is ionic while H2S is metallic.","H2S has no electrons and therefore no dispersion forces.","Covalent O—H bonds break during ordinary boiling."],"Boiling separates molecules without breaking their covalent bonds. Water's highly polar O—H bonds permit strong intermolecular hydrogen bonding, which outweighs the greater dispersion expected from the heavier H₂S molecule.","chem-3.1-imf");
q("U3","3.1","Intermolecular and Interparticle Forces","6.C","Among nonpolar molecules of similar shape, increasing molar mass usually raises boiling point because","larger electron clouds are more polarizable and produce stronger London dispersion forces",["heavier molecules become ionic","covalent bonds inside each molecule become the force overcome by boiling","molecular mass eliminates temporary dipoles"],"London dispersion arises from temporary correlated dipoles. Larger, more polarizable electron clouds generally create stronger instantaneous attractions, so more energy is needed to separate the molecules.","chem-3.1-imf");
q("U3","3.2","Properties of Solids","4.C","Which solid is expected to have a very high melting point and conduct electricity when molten but not as a solid?","An ionic solid such as MgO",["A molecular solid such as solid CO2","A metallic solid such as Cu","A nonpolar molecular solid such as I2"],"Strong electrostatic attractions give ionic solids high melting points. Their ions are immobile in the solid lattice but become mobile charge carriers after melting.","chem-3.2-solids");
q("U3","3.2","Properties of Solids","6.A","A solid is hard, has an extremely high melting point, and does not conduct electricity. Which structure best fits these observations?","A covalent-network solid",["A molecular solid held only by weak dispersion forces","A metallic lattice with delocalized electrons","A liquid solution frozen around mobile ions"],"A three-dimensional network of strong covalent bonds can produce exceptional hardness and a high melting point. If the network lacks mobile electrons or ions, it can also be electrically insulating.","chem-3.2-solids");
q("U3","3.3","Solids, Liquids, and Gases","4.B","Which particle-level statement distinguishes a liquid from a gas at the same temperature?","Liquid particles remain close together while still moving past one another.",["Liquid particles are fixed at lattice sites.","Gas particles have no kinetic energy.","Liquid molecules have different covalent bonds than their vapor."],"Particles in a liquid are close enough for substantial intermolecular interactions but have enough mobility to flow. Gas particles are much farther apart on average and occupy the full container volume.","chem-3.3-states");
q("U3","3.3","Solids, Liquids, and Gases","6.B","During melting of a pure molecular solid at constant pressure, the temperature stays nearly constant because added energy is used mainly to","overcome some intermolecular attractions rather than increase average kinetic energy",["break every covalent bond in the molecules","remove protons from the nuclei","decrease the potential energy of particle separation"],"Temperature tracks average kinetic energy. During a phase change at the melting point, added heat primarily increases intermolecular potential energy as particles reorganize, so temperature remains nearly constant until melting is complete.","chem-3.3-states");
q("U3","3.4","Ideal Gas Law","5.B","What volume does 1.00 mol of an ideal gas occupy at 300 K and 1.00 atm? Use R = 0.0821 L·atm·mol−1·K−1.","24.6 L",["8.21 L","12.3 L","82.1 L"],"Using PV = nRT gives V = (1.00 mol)(0.0821 L·atm·mol⁻¹·K⁻¹)(300 K)/(1.00 atm) = 24.6 L.","chem-3.4-ideal");
q("U3","3.4","Ideal Gas Law","5.D","A sealed flexible container holds a fixed amount of ideal gas at constant pressure. If its absolute temperature doubles, its volume will approximately","double",["halve","remain unchanged","quadruple"],"From PV = nRT, with n and P constant, volume is directly proportional to absolute temperature. Doubling T therefore doubles V for ideal-gas behavior.","chem-3.4-ideal");
q("U3","3.5","Kinetic Molecular Theory","4.D","At the same temperature, samples of He(g) and Xe(g) have the same","average translational kinetic energy",["average molecular speed","molar mass","root-mean-square speed"],"For ideal gases, average translational kinetic energy depends only on absolute temperature. The lighter He atoms move faster on average, but both gases have the same average kinetic energy at the same T.","chem-3.5-kmt");
q("U3","3.5","Kinetic Molecular Theory","5.C","At a fixed temperature, which gas has the greatest root-mean-square speed?","H2",["N2","O2","CO2"],"Root-mean-square speed varies inversely with the square root of molar mass at a fixed temperature. H₂ has the smallest molar mass of the choices and therefore the greatest rms speed.","chem-3.5-kmt");
q("U3","3.6","Deviation from Ideal Gas Law","6.C","Real gases deviate most strongly from ideal behavior at","high pressure and low temperature",["low pressure and high temperature","very low density and high temperature","conditions where particles are extremely far apart"],"High pressure makes molecular volume significant, and low temperature makes intermolecular attractions more influential relative to kinetic energy. Both effects violate assumptions of the ideal-gas model.","chem-3.6-real");
q("U3","3.6","Deviation from Ideal Gas Law","4.D","A real gas has a measured pressure lower than the ideal-gas prediction at moderate density. Which effect most directly explains the lower pressure?","Attractive forces reduce the force and frequency of particle impacts on the container wall.",["Particles have exactly zero volume.","Repulsions disappear at all separations.","The gas molecules stop moving between collisions."],"Intermolecular attractions pull molecules slightly away from the walls and toward one another. This can reduce wall-collision momentum transfer, making the measured pressure lower than the ideal prediction.","chem-3.6-real");
q("U3","3.7","Solutions and Mixtures","5.A","What is the molarity of a solution made by dissolving 0.500 mol NaCl to make 2.00 L of solution?","0.250 M",["0.500 M","1.00 M","4.00 M"],"Molarity is moles of solute divided by liters of solution. Therefore M = 0.500 mol / 2.00 L = 0.250 mol L⁻¹.","chem-3.7-solutions");
q("U3","3.7","Solutions and Mixtures","4.A","Which description best represents an aqueous solution of a soluble ionic compound such as KBr?","Separated K+ and Br− ions dispersed among polar water molecules",["Intact KBr molecules stacked in a crystal lattice","Neutral K and Br atoms floating independently","Only K+ ions because Br− evaporates"],"A soluble ionic compound dissociates into hydrated ions. Polar water molecules surround and stabilize K⁺ and Br⁻ through ion-dipole attractions while maintaining overall charge neutrality.","chem-3.7-solutions");
q("U3","3.8","Representations of Solutions","1.B","In a particle diagram of 0.10 M CaCl2(aq) that assumes complete dissociation, the number ratio Ca2+:Cl− should be","1:2",["1:1","2:1","2:3"],"Each formula unit of CaCl₂ produces one Ca²⁺ ion and two Cl⁻ ions on dissociation. A correct particle representation therefore contains twice as many chloride ions as calcium ions.","chem-3.8-representations");
q("U3","3.8","Representations of Solutions","4.A","A particle diagram shows equal volumes of two NaCl solutions, with twice as many Na+ and Cl− ions in beaker B as in beaker A. Which conclusion follows?","Beaker B has approximately twice the NaCl concentration of beaker A.",["Beaker B has half the concentration of beaker A.","The two solutions have equal concentration because their volumes match.","Beaker A must contain undissolved solid NaCl."],"For equal represented volumes and complete dissociation, twice as many formula-unit equivalents means twice as many moles per volume. The ion count therefore indicates a concentration about twice as large in B.","chem-3.8-representations");
q("U3","3.9","Separation of Solutions and Mixtures","2.C","Which technique is most appropriate for separating two miscible liquids with substantially different boiling points?","Distillation",["Filtration","Paper chromatography of a solid precipitate","Decanting two immiscible layers"],"Distillation exploits differences in volatility and boiling point: the more volatile liquid is vaporized preferentially and then condensed. Filtration cannot separate dissolved miscible liquids.","chem-3.9-separation");
q("U3","3.9","Separation of Solutions and Mixtures","6.A","In paper chromatography, a dye travels farther with the solvent than another dye. A reasonable inference is that the farther-traveling dye","has a greater relative affinity for the mobile phase than for the stationary phase",["must have the greater molar mass","is necessarily ionic while the other is covalent","has no intermolecular interactions with either phase"],"Chromatographic separation reflects competing interactions with mobile and stationary phases. Greater travel generally indicates that the solute spends a larger fraction of time associated with the moving solvent.","chem-3.9-separation");
q("U3","3.10","Solubility","4.D","Why is ethanol miscible with water while hexane has very low solubility in water?","Ethanol can form favorable polar and hydrogen-bonding interactions with water, unlike nonpolar hexane.",["Hexane is ionic and water repels ions.","Ethanol has no carbon atoms.","Water forms stronger covalent bonds with ethanol during dissolution."],"Dissolution is favored when solute-solvent attractions can replace disrupted solute-solute and solvent-solvent attractions. Ethanol's polar O—H group interacts strongly with water; nonpolar hexane cannot compensate as well.","chem-3.10-solubility");
q("U3","3.10","Solubility","6.C","A nonpolar solute is much more soluble in liquid hexane than in water. Which explanation best accounts for the observation?","Dispersion interactions with hexane are more compatible with the solute than the interactions available in highly polar water.",["The solute becomes an ion only in hexane.","Hexane has permanent hydrogen bonds stronger than covalent bonds.","Water molecules have no intermolecular attractions to overcome."],"Nonpolar solutes can interact favorably with nonpolar hexane through dispersion forces, while dissolving them in water would disrupt strong water-water interactions without providing comparable new attractions.","chem-3.10-solubility");
q("U3","3.11","Spectroscopy and the Electromagnetic Spectrum","4.B","Which electromagnetic radiation has the greatest photon energy?","The radiation with the highest frequency",["The radiation with the longest wavelength","Any radiation with the greatest intensity regardless of frequency","All electromagnetic radiation has identical photon energy"],"Photon energy follows E = hν, so energy increases directly with frequency. Because c = λν, the highest-frequency radiation also has the shortest wavelength.","chem-3.11-spectrum");
q("U3","3.11","Spectroscopy and the Electromagnetic Spectrum","6.B","A substance absorbs strongly at one wavelength but transmits most neighboring wavelengths. Which conclusion is justified?","Its particles have an allowed energy transition that matches photons at the absorbed wavelength.",["The substance absorbs every possible photon energy equally.","Absorption proves the sample contains only one atom.","The absorbed wavelength must have zero frequency."],"Selective absorption occurs when photon energy matches an allowed molecular or electronic energy difference. Wavelengths that do not match appropriate transitions are transmitted more strongly.","chem-3.11-spectrum");
q("U3","3.12","Properties of Photons","5.B","What happens to photon energy when wavelength is doubled?","It is halved.",["It doubles.","It quadruples.","It remains unchanged."],"Since E = hc/λ, photon energy is inversely proportional to wavelength. Doubling λ while h and c remain constant reduces the energy of each photon by a factor of two.","chem-3.12-photons");
q("U3","3.12","Properties of Photons","5.C","A photon has frequency ν. Which expression gives its energy?","hν",["h/ν","cν","ν/h"],"Planck's relation is E = hν, where h is Planck's constant and ν is frequency. The speed of light is used to convert between frequency and wavelength, not as a replacement for h.","chem-3.12-photons");
q("U3","3.13","Beer-Lambert Law","5.D","A solution obeys Beer's law. If path length and molar absorptivity are constant and concentration doubles, absorbance will approximately","double",["halve","remain constant","increase by a factor of four"],"Beer-Lambert law is A = εbc. With ε and b fixed, absorbance A is directly proportional to concentration c, so doubling c doubles A within the linear range.","chem-3.13-beer");
q("U3","3.13","Beer-Lambert Law","2.D","A calibration curve of absorbance versus concentration is linear through the origin. An unknown has absorbance halfway between standards of 0.20 M and 0.40 M. What is the best estimate of its concentration?","About 0.30 M",["About 0.10 M","About 0.60 M","Concentration cannot be estimated from a linear calibration"],"For a linear Beer-Lambert calibration, absorbance changes proportionally with concentration. An absorbance midway between the two standards therefore corresponds to a concentration near the midpoint, 0.30 M.","chem-3.13-beer");

// Unit 4 — Chemical Reactions
q("U4","4.1","Introduction for Reactions","1.A","Which particle-level description best represents a chemical reaction?","Atoms are rearranged into new combinations while the total number of each kind of atom is conserved.",["Atoms of one element are converted into atoms of another element.","All chemical bonds disappear without new bonds forming.","The total number of atoms decreases whenever a gas forms."],"Ordinary chemical reactions rearrange nuclei and electrons without changing element identities. Conservation of atoms requires the same number of each element before and after the reaction.","chem-4.1-reactions");
q("U4","4.1","Introduction for Reactions","6.A","A sealed flask loses no mass while a visible precipitate forms after two solutions are mixed. Which claim is best supported?","The reaction conserves matter even though the substances present have changed.",["The precipitate contains newly created protons.","Mass conservation applies only when no solid forms.","The reaction must be a physical change because total mass is constant."],"Formation of a new solid is evidence of a chemical change, while unchanged total mass in the sealed system demonstrates conservation of matter. Chemical identity can change without changing total mass.","chem-4.1-reactions");
q("U4","4.2","Net Ionic Equations","4.A","When AgNO3(aq) and NaCl(aq) are mixed, AgCl(s) forms. Which ions are spectators?","Na+ and NO3−",["Ag+ and Cl−","Ag+ and NO3−","Na+ and Cl−"],"The net ionic reaction is Ag⁺(aq) + Cl⁻(aq) → AgCl(s). Na⁺ and NO₃⁻ remain aqueous and unchanged on both sides, so they cancel as spectator ions.","chem-4.2-netionic");
q("U4","4.2","Net Ionic Equations","5.A","Which net ionic equation represents neutralization of a strong acid by a strong base?","H+(aq) + OH−(aq) → H2O(l)",["Na+(aq) + Cl−(aq) → NaCl(aq)","H2O(l) → H+(aq) + OH−(aq) only","H+(aq) + Cl−(aq) → HCl(s)"],"Strong acids and bases dissociate essentially completely, so their spectator counterions cancel. The chemically changing species are H⁺ and OH⁻, which combine to form liquid water.","chem-4.2-netionic");
q("U4","4.3","Representations of Reactions","1.B","A particulate diagram for 2H2 + O2 → 2H2O should show, before reaction,","twice as many H2 molecules as O2 molecules for a stoichiometric mixture",["equal numbers of H2 and O2 molecules","twice as many O2 molecules as H2 molecules","only individual H and O atoms"],"The balanced coefficients give the molecular ratio consumed by the reaction. A stoichiometric mixture therefore contains two H₂ molecules for every one O₂ molecule, producing two H₂O molecules.","chem-4.3-representations");
q("U4","4.3","Representations of Reactions","4.B","A particle diagram after a reaction shows product particles plus unreacted molecules of reactant A but none of reactant B. Which inference is valid?","B was the limiting reactant in the represented mixture.",["A was the limiting reactant.","No reaction occurred.","Both reactants had identical initial mole amounts."],"If B is completely consumed while A remains, the available amount of B limited how much product could form. Excess A remains after the limiting reactant is exhausted.","chem-4.3-representations");
q("U4","4.4","Physical and Chemical Changes","6.B","Which observation most directly indicates a chemical rather than purely physical change?","A new solid with different chemical composition forms from two clear solutions.",["Ice melts to liquid water.","A metal rod is cut into shorter pieces.","Ethanol evaporates from an open dish."],"A precipitate with a new composition requires rearrangement of atoms and formation of new chemical species. Melting, cutting, and evaporation change physical state or form without changing molecular identity.","chem-4.4-changes");
q("U4","4.4","Physical and Chemical Changes","4.C","When liquid water boils, which interaction is primarily overcome?","Intermolecular attractions between water molecules",["O—H covalent bonds within each water molecule","The nuclei of hydrogen atoms","Electron-proton attractions inside oxygen atoms"],"Boiling separates intact H₂O molecules into the gas phase. It therefore requires overcoming intermolecular attractions, especially hydrogen bonding, rather than breaking the strong covalent O—H bonds within each molecule.","chem-4.4-changes");
q("U4","4.5","Stoichiometry","5.B","For 2H2 + O2 → 2H2O, how many moles of H2O can form from 3.0 mol O2 with excess H2?","6.0 mol",["1.5 mol","3.0 mol","9.0 mol"],"The balanced equation gives 2 mol H₂O per 1 mol O₂. Multiplying 3.0 mol O₂ by the 2:1 stoichiometric ratio gives 6.0 mol H₂O.","chem-4.5-stoich");
q("U4","4.5","Stoichiometry","5.D","For N2 + 3H2 → 2NH3, a mixture contains 2.0 mol N2 and 3.0 mol H2. What is the maximum amount of NH3 that can form?","2.0 mol NH3",["1.0 mol NH3","3.0 mol NH3","4.0 mol NH3"],"Three moles of H₂ produce two moles of NH₃, and the available 3.0 mol H₂ are consumed with only 1.0 mol N₂. H₂ is limiting, so the maximum is 2.0 mol NH₃.","chem-4.5-stoich");
q("U4","4.6","Introduction to Titration","2.B","In an acid-base titration, why is a standardized titrant useful?","Its accurately known concentration allows the analyte amount to be calculated from the delivered volume and reaction stoichiometry.",["It guarantees every acid and base reacts in a 1:1 mole ratio.","It eliminates the need to measure any volume.","Its concentration changes automatically to match the unknown."],"A titration converts a measured titrant volume into moles using a known concentration, then uses the balanced reaction to infer analyte moles. Without a reliable titrant concentration, that calculation is not quantitative.","chem-4.6-titration");
q("U4","4.6","Introduction to Titration","5.C","25.0 mL of HCl is exactly neutralized by 20.0 mL of 0.150 M NaOH. What is the HCl concentration?","0.120 M",["0.0750 M","0.150 M","0.188 M"],"HCl and NaOH react 1:1. The NaOH amount is (0.0200 L)(0.150 mol L⁻¹)=0.00300 mol, so [HCl]=0.00300 mol/0.0250 L=0.120 M.","chem-4.6-titration");
q("U4","4.7","Types of Chemical Reactions","4.C","Which reaction is a precipitation reaction?","Ba2+(aq) + SO4^2−(aq) → BaSO4(s)",["CH4(g) + 2O2(g) → CO2(g) + 2H2O(g)","H+(aq) + OH−(aq) → H2O(l)","2KClO3(s) → 2KCl(s) + 3O2(g)"],"A precipitation reaction produces an insoluble solid from dissolved ions. BaSO₄ is represented as a solid forming from aqueous Ba²⁺ and SO₄²⁻, matching that definition.","chem-4.7-types");
q("U4","4.7","Types of Chemical Reactions","6.A","A hydrocarbon burns completely in excess oxygen. Which products are expected?","CO2 and H2O",["CO and H2 only","C and O2 only","H2O2 and elemental carbon only"],"Complete combustion of a hydrocarbon oxidizes carbon to CO₂ and hydrogen to H₂O when oxygen is abundant. Incomplete combustion can produce CO or soot, but that is not the stated condition.","chem-4.7-types");
q("U4","4.8","Introduction to Acid-Base Reactions","4.D","In the Brønsted-Lowry reaction NH3 + H2O ⇌ NH4+ + OH−, NH3 acts as","a base because it accepts a proton",["an acid because it donates a proton","an oxidizing agent because nitrogen gains oxygen","a spectator because it is unchanged"],"A Brønsted-Lowry base accepts H⁺. NH₃ gains a proton from water to become NH₄⁺, while water donates that proton and becomes OH⁻.","chem-4.8-acidbase");
q("U4","4.8","Introduction to Acid-Base Reactions","6.C","Which pair is a conjugate acid-base pair?","NH4+ and NH3",["HCl and NaCl","Na+ and OH−","H2O and O2"],"Conjugate acid-base partners differ by exactly one proton. NH₄⁺ can donate H⁺ to form NH₃, and NH₃ can accept H⁺ to reform NH₄⁺.","chem-4.8-acidbase");
q("U4","4.9","Oxidation-Reduction (Redox) Reactions","4.B","In Zn(s) + Cu2+(aq) → Zn2+(aq) + Cu(s), which species is oxidized?","Zn(s)",["Cu2+(aq)","Zn2+(aq)","Cu(s)"],"Zn changes oxidation state from 0 to +2, meaning it loses two electrons and is oxidized. Cu²⁺ gains those electrons and is reduced from +2 to 0.","chem-4.9-redox");
q("U4","4.9","Oxidation-Reduction (Redox) Reactions","5.A","What is the oxidation number of sulfur in SO4^2−?","+6",["+2","+4","−2"],"Each oxygen is normally −2, giving −8 total. Because the ion's total charge is −2, sulfur must be +6 so that +6 + (−8) = −2.","chem-4.9-redox");

// Unit 5 — Kinetics
q("U5","5.1","Reaction Rates","5.A","The concentration of a reactant falls from 0.80 M to 0.50 M in 30 s. What is the magnitude of its average disappearance rate?","0.010 M s−1",["0.0030 M s−1","0.030 M s−1","10 M s−1"],"The concentration change magnitude is 0.30 M over 30 s, so the average disappearance rate is 0.30/30 = 0.010 M s⁻¹.","chem-5.1-rate");
q("U5","5.1","Reaction Rates","4.B","On a concentration-versus-time graph for a reactant, the instantaneous reaction rate at a given time is related to","the magnitude of the tangent slope at that time",["the total area under the curve only","the y-intercept regardless of time","the final concentration divided by the initial concentration"],"The derivative d[reactant]/dt is the tangent slope of the concentration-time curve. Reactant concentration decreases, so its slope is negative while the disappearance-rate magnitude is positive.","chem-5.1-rate");
q("U5","5.2","Introduction to Rate Law","5.C","For rate = k[A]^2[B], what happens to the rate if [A] doubles while [B] stays constant?","The rate increases by a factor of 4.",["The rate doubles.","The rate is halved.","The rate increases by a factor of 8."],"The rate depends on [A] squared. Replacing [A] by 2[A] multiplies that factor by 2² = 4, while the unchanged [B] contributes no additional change.","chem-5.2-ratelaw");
q("U5","5.2","Introduction to Rate Law","6.B","Experimental trials show doubling [A] doubles the initial rate, while doubling [B] has no effect. Which rate law is consistent with the data?","rate = k[A]",["rate = k[A]^2[B]","rate = k[B]","rate = k[A][B]"],"A doubling that doubles rate indicates first order in A. No rate change when B doubles indicates zero order in B, so the concentration dependence is rate = k[A].","chem-5.2-ratelaw");
q("U5","5.3","Concentration Changes Over Time","5.B","For a first-order reaction, a plot of which quantity versus time is linear?","ln[A]",["[A]^2","1/[A]^2","sqrt([A])"],"The integrated first-order law is ln[A]t = −kt + ln[A]0. Therefore ln[A] plotted against time gives a straight line with slope −k.","chem-5.3-integrated");
q("U5","5.3","Concentration Changes Over Time","5.D","A first-order reaction has a half-life of 20 min. What fraction of the initial reactant remains after 60 min?","1/8",["1/2","1/3","1/6"],"Sixty minutes corresponds to three 20-minute half-lives. A first-order process halves the remaining amount each half-life, giving (1/2)³ = 1/8 of the initial amount.","chem-5.3-integrated");
q("U5","5.4","Elementary Reactions","4.D","For the elementary step 2A + B → products, the molecularity is","termolecular",["unimolecular","bimolecular","zero-order"],"An elementary step's molecularity counts reacting particles in that single collision event. Two A particles plus one B particle make three reacting species, so the step is termolecular.","chem-5.4-elementary");
q("U5","5.4","Elementary Reactions","5.C","If A + B → products is an elementary bimolecular step, its rate law is expected to be","rate = k[A][B]",["rate = k[A+B]","rate = k[A]^2 only","rate = k/[A][B]"],"For an elementary step, stoichiometric coefficients directly give the reactant orders in its rate law. One A and one B participate, so rate is proportional to [A][B].","chem-5.4-elementary");
q("U5","5.5","Collision Model","4.D","Increasing temperature usually increases reaction rate primarily because","a larger fraction of collisions have enough energy to overcome the activation barrier",["all collisions become perfectly oriented","the activation energy itself necessarily becomes zero","reactant concentration always doubles with temperature"],"A higher temperature shifts the kinetic-energy distribution so more collisions exceed the activation energy. Collision frequency may also rise somewhat, but the increased energetic fraction is especially important.","chem-5.5-collision");
q("U5","5.5","Collision Model","6.C","Two reactions have similar collision frequencies, but reaction X is much slower. Which explanation is consistent with collision theory?","A smaller fraction of X's collisions have sufficient energy and proper orientation to react.",["X must violate conservation of energy.","X has no molecules present.","Every collision in X necessarily forms product."],"Collision theory requires both enough energy to cross the activation barrier and an effective orientation. Similar collision counts can therefore yield very different rates if the successful-collision fraction differs.","chem-5.5-collision");
q("U5","5.6","Reaction Energy Profile","4.B","On a one-step reaction energy diagram, activation energy for the forward reaction is the energy difference between","the reactants and the transition-state peak",["products and reactants only","products and zero energy","two stable intermediates"],"Activation energy is the energetic barrier from the reactant energy level to the transition state. The product-reactant difference instead represents the overall reaction energy change.","chem-5.6-profile");
q("U5","5.6","Reaction Energy Profile","6.B","An energy profile shows products lower in energy than reactants. Which statement is supported?","The forward reaction is exothermic with a negative enthalpy change.",["The forward reaction must have zero activation energy.","The reaction cannot proceed in reverse.","A catalyst would change the reactant-product energy difference."],"Products lying below reactants indicates energy release and ΔH < 0. The activation barrier can still be substantial, reversibility is possible, and a catalyst does not change ΔH.","chem-5.6-profile");
q("U5","5.7","Introduction to Reaction Mechanisms","4.A","In a proposed mechanism, a species is produced in one elementary step and consumed in a later step but does not appear in the overall equation. It is","an intermediate",["a catalyst necessarily","a spectator ion necessarily","the limiting reactant"],"An intermediate is formed during the mechanism and then consumed, so it cancels when elementary steps are summed. A catalyst instead is consumed first and regenerated later.","chem-5.7-mechanism");
q("U5","5.7","Introduction to Reaction Mechanisms","6.A","A valid reaction mechanism must, at minimum,","sum to the overall reaction and be consistent with the experimentally observed rate behavior",["contain only one elementary step","include the overall stoichiometric coefficients in every rate law","have no intermediates"],"A proposed mechanism must reproduce the net chemical equation and explain kinetic evidence. Mechanisms may contain several steps and intermediates, so those features do not invalidate them.","chem-5.7-mechanism");
q("U5","5.8","Reaction Mechanism and Rate Law","5.C","A mechanism's slow elementary step is A + 2B → products. If that step controls the rate and occurs as written, which rate law is predicted?","rate = k[A][B]^2",["rate = k[A+B]","rate = k[A]^2[B]","rate = k[B] only"],"For an elementary rate-determining step, the molecular stoichiometry determines the concentration exponents. One A and two B particles give rate = k[A][B]².","chem-5.8-mechrate");
q("U5","5.8","Reaction Mechanism and Rate Law","6.B","An experimentally measured rate law contains no [C] term even though C appears in the overall balanced equation. Which conclusion is justified?","The overall equation alone does not determine the rate law; C does not affect the rate under the measured mechanism/conditions.",["C cannot participate in any elementary step.","The balanced equation must be wrong.","C must be a product rather than a reactant."],"Rate laws are determined experimentally and reflect mechanism, not simply overall stoichiometric coefficients. A reactant can appear in the net equation without its concentration affecting the observed rate law.","chem-5.8-mechrate");
q("U5","5.9","Pre-Equilibrium Approximation","5.F","A mechanism begins with fast equilibrium A + B ⇌ I, followed by slow I → P. If K = [I]/([A][B]), the slow-step rate k2[I] can be written as","rate = k2K[A][B]",["rate = k2/[A][B]","rate = K/[I]","rate = k2[A]/[B]"],"The pre-equilibrium relation gives [I] = K[A][B]. Substituting this expression for the intermediate into the slow-step law rate = k₂[I] yields rate = k₂K[A][B].","chem-5.9-preeq");
q("U5","5.9","Pre-Equilibrium Approximation","6.C","Why is the pre-equilibrium approximation useful in deriving a rate law?","It expresses an intermediate concentration in terms of measurable reactant concentrations using an earlier fast equilibrium.",["It assumes every elementary step has the same rate constant.","It removes the activation energy from the reaction.","It makes the equilibrium constant equal to zero."],"Intermediates generally cannot appear in the final experimental rate law. A rapidly established equilibrium supplies an algebraic relationship that replaces the intermediate concentration with reactant concentrations.","chem-5.9-preeq");
q("U5","5.10","Multistep Reaction Energy Profile","4.B","A multistep energy diagram has two peaks separated by a valley. The valley most directly represents","an intermediate",["the transition state of the first step","the activation energy itself","the final products necessarily"],"Peaks correspond to transition states, while a local minimum between peaks corresponds to a species with finite lifetime relative to transition states—an intermediate formed and then consumed.","chem-5.10-multistep");
q("U5","5.10","Multistep Reaction Energy Profile","6.B","For a two-step mechanism, the first transition-state peak is much higher above its preceding minimum than the second peak is above its preceding minimum. Which step is expected to be slower, all else equal?","The first step",["The second step","Both must have identical rates","Neither step can occur"],"A larger activation barrier generally corresponds to a smaller rate constant at the same temperature. The first step therefore has the stronger kinetic barrier and is expected to be slower.","chem-5.10-multistep");
q("U5","5.11","Catalysis","4.D","A catalyst increases reaction rate by","providing an alternative mechanism with a lower activation-energy pathway",["making the overall ΔG more negative","increasing the equilibrium constant","raising the energies of the products permanently"],"A catalyst changes the kinetic pathway and lowers the barrier for forward and reverse reactions. It does not change the thermodynamic energy difference between reactants and products or the equilibrium constant.","chem-5.11-catalysis");
q("U5","5.11","Catalysis","6.C","A catalyst is added to a system already at equilibrium. What happens?","Forward and reverse rates both increase, but equilibrium composition remains unchanged.",["Only the forward rate increases and products accumulate.","The equilibrium constant increases.","The reaction enthalpy becomes zero."],"Catalysts lower activation barriers for both directions and therefore speed the approach to equilibrium without changing ΔG°, K, or the equilibrium composition at a fixed temperature.","chem-5.11-catalysis");

// Unit 6 — Thermochemistry
q("U6","6.1","Endothermic and Exothermic Processes","4.B","For an exothermic process at constant pressure, the system's enthalpy change is","negative",["positive","always zero","undefined because heat cannot flow"],"At constant pressure, heat released by the system corresponds to q_p < 0, and ΔH = q_p. Therefore an exothermic process has a negative enthalpy change for the system.","chem-6.1-endoexo");
q("U6","6.1","Endothermic and Exothermic Processes","6.A","An instant cold pack becomes colder when its contents are mixed. Which statement best describes the process occurring inside the pack?","The process is endothermic and absorbs thermal energy from the surroundings.",["The process is exothermic and releases heat into the hand.","No energy transfer occurs because temperature changes.","The process must have ΔH = 0."],"Cooling of the surroundings indicates energy flows from the surroundings into the chemical system. That heat absorption is the defining sign of an endothermic process under the stated conditions.","chem-6.1-endoexo");
q("U6","6.2","Energy Diagrams","4.A","On an enthalpy diagram for an exothermic reaction, the products should be drawn","below the reactants",["above the reactants","at an unrelated arbitrary height","at the activation-energy peak"],"For an exothermic reaction, H_products < H_reactants and ΔH is negative. An energy-level diagram therefore places the product line below the reactant line.","chem-6.2-diagrams");
q("U6","6.2","Energy Diagrams","5.A","Reactants lie at 150 kJ mol−1 and products at 90 kJ mol−1 on an enthalpy diagram. What is ΔH for the reaction?","−60 kJ mol−1",["+60 kJ mol−1","−240 kJ mol−1","+240 kJ mol−1"],"Reaction enthalpy is H_products − H_reactants = 90 − 150 = −60 kJ mol⁻¹. The negative sign indicates the products are lower in enthalpy.","chem-6.2-diagrams");
q("U6","6.3","Heat Transfer and Thermal Equilibrium","4.D","Two objects at different temperatures are placed in thermal contact in an insulated enclosure. Net heat flows","from the hotter object to the colder object until thermal equilibrium is reached",["from the colder object to the hotter object indefinitely","only if the objects have equal masses","without any change in either object's internal energy"],"Spontaneous thermal energy transfer occurs from higher to lower temperature. In an insulated pair, the transfer continues until both objects reach the same equilibrium temperature.","chem-6.3-transfer");
q("U6","6.3","Heat Transfer and Thermal Equilibrium","6.B","In an ideal insulated calorimeter, a hot metal sample loses 500 J of heat to water. What heat change does the water experience?","+500 J",["−500 J","0 J","+1000 J"],"Energy conservation in the insulated calorimeter gives q_metal + q_water = 0. If the metal loses 500 J, q_metal = −500 J and the water gains +500 J.","chem-6.3-transfer");
q("U6","6.4","Heat Capacity and Calorimetry","5.B","How much heat is required to raise 100 g of water by 5.0°C? Use c = 4.18 J g−1 °C−1.","2.09×10^3 J",["83.6 J","418 J","20.9×10^3 J"],"Using q = mcΔT gives (100 g)(4.18 J g⁻¹ °C⁻¹)(5.0°C) = 2090 J = 2.09×10³ J.","chem-6.4-calorimetry");
q("U6","6.4","Heat Capacity and Calorimetry","5.D","Equal masses of substances X and Y absorb the same amount of heat. X undergoes a smaller temperature increase. Compared with Y, X has","a larger specific heat capacity",["a smaller specific heat capacity","the same specific heat necessarily","zero heat capacity"],"From q = mcΔT, with q and m equal, c is inversely related to ΔT. The substance with the smaller temperature rise must have the larger specific heat capacity.","chem-6.4-calorimetry");
q("U6","6.5","Energy of Phase Changes","5.C","How much energy is required to vaporize 2.0 mol of a liquid if ΔHvap = 30 kJ mol−1 at its boiling point?","60 kJ",["15 kJ","30 kJ","90 kJ"],"For a phase change at the stated conditions, q = nΔH_vap = (2.0 mol)(30 kJ mol⁻¹) = 60 kJ absorbed.","chem-6.5-phase");
q("U6","6.5","Energy of Phase Changes","6.B","Why does vaporization require energy even while temperature remains constant at the boiling point?","Energy is used to increase intermolecular potential energy as molecules separate.",["Energy is used to lower molecular kinetic energy to zero.","Every covalent bond inside each molecule must break.","The vapor contains less total energy than the liquid."],"During boiling, average kinetic energy and therefore temperature remain approximately constant. Added energy instead weakens intermolecular attractions and separates molecules, increasing their potential energy.","chem-6.5-phase");
q("U6","6.6","Introduction to Enthalpy of Reaction","5.A","If a reaction releases 125 kJ when 2.00 mol of product forms, what is ΔH per mole of product?","−62.5 kJ mol−1",["+62.5 kJ mol−1","−250 kJ mol−1","+250 kJ mol−1"],"Released heat makes the reaction enthalpy negative. Dividing −125 kJ by 2.00 mol of product gives −62.5 kJ per mole of product formed.","chem-6.6-enthalpy");
q("U6","6.6","Introduction to Enthalpy of Reaction","6.A","If a thermochemical equation is reversed, its ΔH value","changes sign but keeps the same magnitude",["is squared","becomes zero","keeps the same sign and magnitude"],"Enthalpy is a state function. Reversing initial and final states reverses H_final − H_initial, so the sign changes while the magnitude for the exact reverse process is unchanged.","chem-6.6-enthalpy");
q("U6","6.7","Bond Enthalpies","5.C","Using average bond enthalpies, ΔH for a reaction is estimated by","sum of bond energies broken minus sum of bond energies formed",["sum formed minus sum broken","sum of all bond energies with no signs","product molar mass minus reactant molar mass"],"Breaking bonds requires energy while forming bonds releases energy. The bond-enthalpy estimate therefore adds energies required for broken bonds and subtracts energies released when new bonds form.","chem-6.7-bondenthalpy");
q("U6","6.7","Bond Enthalpies","6.C","A reaction forms stronger bonds in the products than the bonds it breaks in the reactants. What is generally expected?","The reaction tends to be exothermic because bond formation releases more energy than bond breaking requires.",["The reaction must be endothermic because strong bonds contain more usable heat.","ΔH must be exactly zero.","No conclusion is possible even qualitatively from bond strengths."],"If the energy released by forming strong product bonds exceeds the energy required to break reactant bonds, the net enthalpy change is negative, corresponding to an exothermic reaction.","chem-6.7-bondenthalpy");
q("U6","6.8","Enthalpy of Formation","5.F","Using standard enthalpies of formation, reaction enthalpy is calculated as","ΣνΔHf°(products) − ΣνΔHf°(reactants)",["ΣνΔHf°(reactants) − ΣνΔHf°(products)","the largest single ΔHf° value","the sum of coefficients without enthalpy values"],"Because enthalpy is a state function, standard reaction enthalpy equals the stoichiometric sum of product formation enthalpies minus the corresponding reactant sum.","chem-6.8-formation");
q("U6","6.8","Enthalpy of Formation","5.B","What is ΔHf° for an element in its standard state, such as O2(g) at 1 bar and 25°C?","0 kJ mol−1",["1 kJ mol−1","−273 kJ mol−1","It is always positive and unknown."],"By convention, the standard enthalpy of formation of an element in its reference standard state is defined as zero. This provides the common baseline for formation enthalpy tables.","chem-6.8-formation");
q("U6","6.9","Hess’s Law","5.D","Reaction A has ΔH = +40 kJ and reaction B has ΔH = −65 kJ. If the equations are added directly to obtain a target reaction, what is the target ΔH?","−25 kJ",["+25 kJ","+105 kJ","−105 kJ"],"Hess's law allows enthalpy changes to be added when reaction equations are added. Thus ΔH_target = +40 kJ + (−65 kJ) = −25 kJ.","chem-6.9-hess");
q("U6","6.9","Hess’s Law","6.C","Why can Hess's law be used even when the actual reaction mechanism is unknown?","Enthalpy is a state function, so its change depends only on initial and final states, not the path between them.",["Every reaction follows the same mechanism.","Activation energy is also a state function and equals ΔH.","All intermediate enthalpies are zero."],"State functions are path independent. Any sequence of hypothetical reactions connecting the same reactants and products has a summed enthalpy change equal to the direct reaction's ΔH.","chem-6.9-hess");

// Unit 7 — Equilibrium
q("U7","7.1","Introduction to Equilibrium","4.D","At dynamic equilibrium in a closed system, which statement is true?","Forward and reverse reaction rates are equal even though both reactions continue.",["Reactant and product concentrations must be equal.","All molecular motion stops.","The forward reaction has stopped while the reverse reaction continues."],"Dynamic equilibrium means opposing processes continue at equal rates, so macroscopic concentrations remain constant. Equal rates do not require equal reactant and product concentrations.","chem-7.1-equilibrium");
q("U7","7.1","Introduction to Equilibrium","6.B","A concentration-time graph becomes flat for both reactant and product after 200 s. Which additional evidence best supports that equilibrium has been reached?","Measurements show the forward and reverse reaction rates are equal after 200 s.",["The reactant concentration is zero.","The product concentration equals the reactant concentration exactly.","The temperature is necessarily 0°C."],"Constant concentrations are consistent with equilibrium, and equal forward and reverse rates establish the dynamic balance that causes those concentrations to remain unchanged with time.","chem-7.1-equilibrium");
q("U7","7.2","Direction of Reversible Reactions","4.C","For A ⇌ B, a mixture initially contains only A. Immediately after mixing under conditions where both directions are possible, the net reaction proceeds","toward B because the forward rate is initially nonzero while the reverse rate is initially zero",["toward A because no B is present","in neither direction because reversible reactions cannot start from pure reactant","equally in both directions from the first instant"],"With A present, forward collisions can occur immediately. With no B initially, the reverse reaction has no reactant particles and starts at zero rate, so net change is toward B until B accumulates.","chem-7.2-direction");
q("U7","7.2","Direction of Reversible Reactions","6.C","A reversible reaction mixture is not at equilibrium and is observed to produce net reactant over time. Which rate relationship must hold during that interval?","The reverse rate exceeds the forward rate.",["The forward rate exceeds the reverse rate.","Both rates are zero.","The forward and reverse rates are equal."],"Net formation of reactant means the reverse process is occurring faster than the forward process. Equal rates would produce no net composition change, which defines equilibrium.","chem-7.2-direction");
q("U7","7.3","Reaction Quotient and Equilibrium Constant","5.C","For A(g) ⇌ 2B(g), which expression is Qc?","[B]^2/[A]",["[A]/[B]^2","2[B]/[A]","[B]/2[A]"],"The reaction quotient has the same algebraic form as the equilibrium constant: product concentrations over reactant concentrations, each raised to its stoichiometric coefficient. Thus Qc=[B]²/[A].","chem-7.3-qk");
q("U7","7.3","Reaction Quotient and Equilibrium Constant","6.B","If Q < K for a reaction at fixed temperature, the system will tend to","proceed in the forward direction until Q rises to K",["proceed in reverse until Q becomes still smaller","remain unchanged because Q never affects direction","change the value of K until it equals Q"],"When Q is smaller than K, the mixture has too much reactant relative to the equilibrium ratio. Net forward reaction increases products and decreases reactants until Q reaches K.","chem-7.3-qk");
q("U7","7.4","Calculating the Equilibrium Constant","5.D","For A ⇌ B, equilibrium concentrations are [A]=0.20 M and [B]=0.80 M. What is Kc?","4.0",["0.25","0.60","1.0"],"For the 1:1 reaction, Kc=[B]/[A]. Substituting the equilibrium values gives 0.80/0.20 = 4.0.","chem-7.4-calcK");
q("U7","7.4","Calculating the Equilibrium Constant","5.F","For N2O4(g) ⇌ 2NO2(g), equilibrium concentrations are [N2O4]=0.50 M and [NO2]=0.20 M. What is Kc?","0.080",["0.20","0.40","5.0"],"Kc=[NO₂]²/[N₂O₄]=(0.20)²/0.50=0.040/0.50=0.080. The coefficient 2 on NO₂ becomes an exponent in the equilibrium expression.","chem-7.4-calcK");
q("U7","7.5","Magnitude of the Equilibrium Constant","4.D","A reaction has K = 2×10^8 at a certain temperature. Which statement best describes its equilibrium mixture?","Products are strongly favored, though some reactant can remain.",["Reactants and products must be present in exactly equal amounts.","Reactants are overwhelmingly favored.","The reaction reaches completion with mathematically zero reactant in every case."],"A very large K means the equilibrium ratio strongly favors products. Equilibrium is not the same as irreversible completion, so a small amount of reactant may still be present.","chem-7.5-magnitude");
q("U7","7.5","Magnitude of the Equilibrium Constant","6.C","Two reactions have K values 10^−6 and 10^3 at the same temperature. Which reaction is more product-favored at equilibrium?","The reaction with K = 10^3",["The reaction with K = 10^−6","Both are equally product-favored because K is unitless","Product favorability cannot be related to K"],"K compares equilibrium product activities to reactant activities in the expression for the reaction. Values much greater than 1 indicate product-favored equilibria; values much less than 1 indicate reactant-favored equilibria.","chem-7.5-magnitude");
q("U7","7.6","Properties of the Equilibrium Constant","5.A","If a reaction has equilibrium constant K, what is the equilibrium constant for the reverse reaction at the same temperature?","1/K",["K","−K","K^2"],"Reversing the reaction swaps numerator and denominator in the equilibrium expression. Therefore the equilibrium constant becomes the reciprocal, 1/K.","chem-7.6-properties");
q("U7","7.6","Properties of the Equilibrium Constant","5.C","If every coefficient in a balanced equilibrium reaction is multiplied by 2, the new equilibrium constant is","K^2",["2K","K/2","sqrt(K)"],"Multiplying all stoichiometric coefficients by 2 doubles every exponent in the equilibrium expression, which squares the original expression and therefore gives K_new = K².","chem-7.6-properties");
q("U7","7.7","Calculating Equilibrium Concentrations","5.D","For A ⇌ B, Kc=4.0. Initially [A]=1.0 M and [B]=0. If x M of A reacts, which equation determines x?","x/(1.0−x)=4.0",["(1.0−x)/x=4.0","x(1.0−x)=4.0","1.0/x=4.0"],"At equilibrium [A]=1.0−x and [B]=x. Because Kc=[B]/[A], substitution gives x/(1.0−x)=4.0.","chem-7.7-concentrations");
q("U7","7.7","Calculating Equilibrium Concentrations","5.F","For A ⇌ B with Kc=1.0, a system starts with [A]=1.0 M and [B]=0. What are the equilibrium concentrations?","[A]=0.50 M and [B]=0.50 M",["[A]=1.0 M and [B]=1.0 M","[A]=0 and [B]=1.0 M","[A]=0.75 M and [B]=0.25 M"],"Let x convert from A to B. Then Kc=x/(1.0−x)=1, so x=0.50 M. Thus both equilibrium concentrations are 0.50 M.","chem-7.7-concentrations");
q("U7","7.8","Representations of Equilibrium","1.B","A particle diagram for A ⇌ B at equilibrium is sampled at two different times. Which observation is expected?","The numbers of A and B particles fluctuate microscopically but remain near constant average proportions.",["All particles stop converting between A and B.","Every A particle converts to B and remains there.","The number of each species must alternate between zero and the total."],"Equilibrium is dynamic at the molecular scale. Individual conversion events continue, but equal average forward and reverse rates maintain statistically stable macroscopic composition.","chem-7.8-representations");
q("U7","7.8","Representations of Equilibrium","4.B","A particle diagram initially shows many A particles and few B particles. Later diagrams stabilize with fewer A and more B. Which graph matches the approach to equilibrium?","[A] decreases toward a plateau while [B] increases toward a plateau.",["Both concentrations decrease to zero.","[A] increases without limit while [B] remains zero.","Both concentrations oscillate with ever-growing amplitude."],"Net forward conversion initially consumes A and forms B. As equilibrium is approached, the rates balance and both concentrations become constant, giving opposite trends that level off.","chem-7.8-representations");
q("U7","7.9","Introduction to Le Châtelier’s Principle","4.D","For N2(g)+3H2(g) ⇌ 2NH3(g), decreasing the container volume at constant temperature tends to shift equilibrium","toward NH3 because that side has fewer moles of gas",["toward N2 and H2 because that side has fewer gas particles","in neither direction because pressure cannot affect gas equilibria","toward whichever side is endothermic, regardless of gas moles"],"Compression favors the side with fewer moles of gas because that shift partially counteracts the pressure increase. The product side has 2 gas moles versus 4 on the reactant side.","chem-7.9-lechatelier");
q("U7","7.9","Introduction to Le Châtelier’s Principle","6.C","Adding more reactant to a system at equilibrium often causes a shift toward products because","the system consumes some of the added reactant as it reestablishes equilibrium",["the equilibrium constant becomes permanently larger","the catalyst concentration necessarily increases","all products are removed instantly"],"Changing concentration changes Q, not K at fixed temperature. Adding reactant usually makes Q smaller than K, so net forward reaction occurs until the equilibrium ratio is restored.","chem-7.9-lechatelier");
q("U7","7.10","Reaction Quotient and Le Châtelier’s Principle","5.C","For A ⇌ B with K=2, an equilibrium mixture has [A]=0.50 M and [B]=1.0 M. If B is suddenly removed so [B]=0.20 M, the new Q is","0.40",["2.0","2.5","5.0"],"For this reaction Q=[B]/[A]. Immediately after removal, before any shift occurs, Q=0.20/0.50=0.40, which is below K and predicts net forward reaction.","chem-7.10-qlechatelier");
q("U7","7.10","Reaction Quotient and Le Châtelier’s Principle","6.B","After a disturbance, Q is calculated to be greater than K. What net change occurs as equilibrium is restored?","Products are consumed and reactants form, lowering Q toward K.",["More products form, increasing Q further.","K changes to match Q without composition change.","Both forward and reverse reactions stop."],"Q>K means the product-to-reactant ratio is larger than the equilibrium value. Net reverse reaction decreases numerator terms and increases denominator terms until Q returns to K.","chem-7.10-qlechatelier");
q("U7","7.11","Introduction to Solubility Equilibria","5.C","For AgCl(s) ⇌ Ag+(aq)+Cl−(aq), which expression is Ksp?","[Ag+][Cl−]",["[AgCl][Ag+][Cl−]","[AgCl]/([Ag+][Cl−])","[Ag+]+[Cl−]"],"Pure solid AgCl has constant activity and is omitted from the equilibrium expression. The solubility-product constant is therefore the product of dissolved ion concentrations, [Ag⁺][Cl⁻].","chem-7.11-ksp");
q("U7","7.11","Introduction to Solubility Equilibria","5.D","If the molar solubility of AgCl in pure water is s, which relationship applies?","Ksp=s^2",["Ksp=2s","Ksp=s/2","Ksp=1/s^2"],"Each mole of AgCl that dissolves produces one mole each of Ag⁺ and Cl⁻, so [Ag⁺]=[Cl⁻]=s and Ksp=[Ag⁺][Cl⁻]=s².","chem-7.11-ksp");
q("U7","7.12","Common-Ion Effect","4.D","Adding NaCl to a saturated AgCl solution decreases AgCl solubility because","the added Cl− shifts AgCl(s) ⇌ Ag+ + Cl− toward the solid",["Na+ chemically destroys the AgCl lattice","Ksp becomes smaller solely because concentration changed","the added salt removes all water molecules"],"Adding the common ion Cl⁻ increases Qsp. The equilibrium responds by forming more solid AgCl until Qsp again equals the unchanged Ksp at that temperature.","chem-7.12-commonion");
q("U7","7.12","Common-Ion Effect","6.C","Compared with pure water, CaF2 is generally less soluble in a solution already containing F−. Which explanation is correct?","The common F− ion raises the dissolution reaction quotient and favors precipitation.",["F− changes the identity of Ca2+ into a neutral atom.","The presence of F− makes Ksp exactly zero.","Common ions always increase the entropy of dissolution enough to force more solid to dissolve."],"For CaF₂(s) ⇌ Ca²⁺ + 2F⁻, added F⁻ increases the ion product. To restore Qsp=Ksp, the equilibrium shifts toward solid, reducing the amount that dissolves.","chem-7.12-commonion");

// Unit 8 — Acids and Bases
q("U8","8.1","Introduction to Acids and Bases","4.D","According to Brønsted-Lowry theory, an acid is a species that","donates a proton",["accepts an electron pair only","always contains oxygen","produces electrons in every reaction"],"A Brønsted-Lowry acid transfers H⁺ to a base, while the base accepts that proton. This definition applies more broadly than identifying acids by a particular element such as oxygen.","chem-8.1-intro");
q("U8","8.1","Introduction to Acids and Bases","6.B","In HCl + H2O → H3O+ + Cl−, which species acts as the base?","H2O",["HCl","H3O+","Cl− only because it is negative"],"Water accepts a proton from HCl to form H₃O⁺, so water is the Brønsted-Lowry base in the forward reaction. HCl is the proton donor and therefore the acid.","chem-8.1-intro");
q("U8","8.2","pH and pOH of Strong Acids and Bases","5.B","What is the pH of 1.0×10^−3 M HCl at 25°C, assuming complete dissociation?","3.00",["1.00","7.00","11.00"],"Strong HCl supplies approximately 1.0×10⁻³ M H₃O⁺. Therefore pH = −log(1.0×10⁻³) = 3.00.","chem-8.2-ph");
q("U8","8.2","pH and pOH of Strong Acids and Bases","5.D","At 25°C, a solution has pOH=4.00. What is its pH?","10.00",["3.00","4.00","18.00"],"At 25°C, pH + pOH = 14.00. Substituting pOH=4.00 gives pH=14.00−4.00=10.00.","chem-8.2-ph");
q("U8","8.3","Weak Acid and Base Equilibria","5.C","For weak acid HA with initial concentration C and small dissociation x, which expression approximates Ka?","x^2/C",["C/x^2","x/C^2","C−x only"],"For HA ⇌ H⁺+A⁻, Ka=x²/(C−x). When x is small relative to C, C−x≈C, giving the common approximation Ka≈x²/C.","chem-8.3-weak");
q("U8","8.3","Weak Acid and Base Equilibria","6.C","Two 0.10 M weak acids have Ka values 10^−3 and 10^−6. Which has the lower pH?","The acid with Ka=10^−3",["The acid with Ka=10^−6","They must have identical pH because concentrations match.","Ka cannot be related to acid strength."],"At equal formal concentration, the larger Ka corresponds to greater ionization and a larger equilibrium [H₃O⁺]. Therefore the acid with Ka=10⁻³ has the lower pH.","chem-8.3-weak");
q("U8","8.4","Acid-Base Reactions and Buffers","4.D","When a small amount of strong acid is added to a buffer containing HA and A−, the added H+ is consumed mainly by","A− to form HA",["HA to form A2−","water to form O2","an inert spectator ion that disappears"],"The conjugate base component A⁻ reacts with added H⁺ to form weak acid HA. This removes most of the added strong acid and limits the change in pH.","chem-8.4-bufferreaction");
q("U8","8.4","Acid-Base Reactions and Buffers","5.A","A solution initially contains equal moles of HA and A−. Adding a small amount of NaOH will primarily","convert some HA to A−",["convert A− to HA","destroy both buffer components completely","leave the amounts of HA and A− unchanged"],"Added OH⁻ is neutralized by the weak acid component: HA + OH⁻ → A⁻ + H₂O. Thus HA decreases and A⁻ increases while the pH changes only modestly if buffer capacity is not exceeded.","chem-8.4-bufferreaction");
q("U8","8.5","Acid-Base Titrations","4.B","At the equivalence point of a strong acid-strong base titration at 25°C, the pH is approximately","7",["1","5","13"],"At equivalence, stoichiometric amounts of strong acid and strong base have neutralized one another. The remaining spectator-ion solution is approximately neutral, giving pH near 7 at 25°C.","chem-8.5-titrations");
q("U8","8.5","Acid-Base Titrations","6.B","The equivalence point in a weak-acid/strong-base titration occurs at pH above 7 because","the conjugate base of the weak acid hydrolyzes water to produce OH−",["excess strong acid remains at equivalence","the weak acid becomes a stronger acid after neutralization","water's Kw becomes zero"],"At equivalence the weak acid has been converted largely to its conjugate base. That base reacts with water to form some OH⁻, making the solution basic.","chem-8.5-titrations");
q("U8","8.6","Molecular Structure of Acids and Bases","4.D","For oxyacids with the same central atom, acid strength generally increases as the number of terminal oxygen atoms increases because","additional electronegative oxygen atoms stabilize the conjugate base by withdrawing and delocalizing electron density",["more oxygen atoms always make the O—H bond nonpolar","the molecule becomes a metal","the conjugate base loses all resonance structures"],"Additional oxygens can increase inductive electron withdrawal and provide resonance stabilization for the conjugate base. Greater conjugate-base stabilization favors proton donation and stronger acidity.","chem-8.6-structure");
q("U8","8.6","Molecular Structure of Acids and Bases","6.C","HF is a weaker acid in water than HCl despite fluorine being more electronegative. Which factor is especially important?","The H—F bond is much stronger and harder to break than the H—Cl bond.",["HF contains no polar bond.","HCl cannot ionize in water.","Fluorine has fewer valence electrons than hydrogen."],"Acid strength reflects the energetics of proton transfer, not electronegativity alone. The unusually strong H—F bond resists dissociation, while the weaker H—Cl bond permits essentially complete ionization in water.","chem-8.6-structure");
q("U8","8.7","pH and pKa","5.B","A weak acid has Ka=1.0×10^−5. What is its pKa?","5.00",["−5.00","1.0×10^5","9.00"],"pKa is defined as −log Ka. Therefore −log(1.0×10⁻⁵)=5.00; a smaller pKa corresponds to a larger Ka and a stronger acid.","chem-8.7-pka");
q("U8","8.7","pH and pKa","6.C","Acid X has pKa=2 and acid Y has pKa=5. Which statement is correct?","X is the stronger acid because its Ka is larger.",["Y is stronger because larger pKa means more dissociation.","They have identical Ka values.","pKa contains no information about relative acid strength."],"Because pKa = −log Ka, a lower pKa means a larger equilibrium constant for proton donation. Acid X therefore ionizes more strongly than acid Y under comparable conditions.","chem-8.7-pka");
q("U8","8.8","Properties of Buffers","4.C","Which mixture can function as a buffer?","A weak acid and a significant amount of its conjugate base",["Only a strong acid in water","Only a strong base in water","Equal amounts of a strong acid and strong base after complete neutralization"],"A buffer needs a conjugate weak acid-base pair capable of consuming added OH⁻ or H⁺. A weak acid together with its conjugate base supplies both components needed for this response.","chem-8.8-properties");
q("U8","8.8","Properties of Buffers","6.A","A buffer resists pH change most effectively when small added acid or base does not consume a large fraction of either buffer component. This is because","both conjugate partners remain available to neutralize the disturbance",["the buffer keeps [H+] mathematically fixed under any addition","the equilibrium constant changes after each addition","water no longer participates in proton transfer"],"Buffer action depends on having appreciable amounts of both weak acid and conjugate base. If one component is nearly exhausted, the solution can no longer neutralize additions in both directions effectively.","chem-8.8-properties");
q("U8","8.9","Henderson-Hasselbalch Equation","5.C","For a buffer where [A−]=[HA], the Henderson-Hasselbalch equation predicts","pH=pKa",["pH=0","pH=14−pKa in every case","pH=2pKa"],"The equation is pH=pKa+log([A⁻]/[HA]). When the concentrations are equal, the ratio is 1 and log 1=0, so pH=pKa.","chem-8.9-hh");
q("U8","8.9","Henderson-Hasselbalch Equation","5.D","A buffer has pKa=4.76 and [A−]/[HA]=10. What is its pH?","5.76",["3.76","4.76","14.76"],"Using pH=pKa+log([A⁻]/[HA]), the logarithm of 10 is 1.00. Thus pH=4.76+1.00=5.76.","chem-8.9-hh");
q("U8","8.10","Buffer Capacity","4.D","Which change generally increases the capacity of a buffer without greatly changing its initial pH?","Increasing both HA and A− concentrations by the same factor",["Diluting both components by a large factor","Removing nearly all A−","Adding enough strong acid to consume all A−"],"Keeping the HA:A⁻ ratio fixed keeps pH nearly unchanged, while increasing the absolute amounts provides more moles of each component to neutralize added acid or base before the ratio changes substantially.","chem-8.10-capacity");
q("U8","8.10","Buffer Capacity","6.B","Two buffers have the same HA:A− ratio, but buffer X contains ten times the concentration of both components. Which statement is expected?","They have similar initial pH, but X has greater buffer capacity.",["X has a pH exactly 10 units higher.","The dilute buffer has greater capacity.","Neither solution can resist added strong acid."],"Initial pH depends mainly on the conjugate-base/acid ratio, while capacity depends on the absolute amounts available. Increasing both concentrations preserves the ratio but allows more neutralization before large pH change.","chem-8.10-capacity");
q("U8","8.11","pH and Solubility","4.D","A sparingly soluble metal hydroxide, M(OH)2(s), is placed in acidic solution. Compared with pure water, its solubility usually increases because","H+ consumes OH−, shifting the dissolution equilibrium toward more dissolved ions",["H+ is a common ion for the dissolution reaction","acid always decreases every Ksp value","M2+ is converted into electrons"],"Removing a dissolution product drives M(OH)₂(s) ⇌ M²⁺ + 2OH⁻ to the right. Added H⁺ reacts with OH⁻ to form water, lowering [OH⁻] and allowing more solid to dissolve.","chem-8.11-phsolubility");
q("U8","8.11","pH and Solubility","6.C","Why does lowering pH have little direct effect on the solubility of a salt whose anion is the conjugate base of a strong acid?","That anion is too weak a base to be protonated substantially, so acid does not effectively remove it from the dissolution equilibrium.",["Strong-acid conjugate bases react completely with H+ to form stronger bases.","pH can affect only gases, never ionic solids.","The salt's ions stop interacting with water at low pH."],"Acid-enhanced solubility requires protonation of an anion to reduce its free concentration. Conjugate bases of strong acids are extremely weak bases, so this removal pathway is generally insignificant.","chem-8.11-phsolubility");

// Unit 9 — Thermodynamics and Electrochemistry
q("U9","9.1","Introduction to Entropy","4.D","Which process generally increases the entropy of a substance?","Vaporization of a liquid to a gas",["Freezing a liquid into an ordered solid","Condensing a gas to a liquid","Crystallizing ions from solution"],"A gas has many more accessible positional and energetic microstates than the corresponding liquid. Vaporization therefore increases dispersal of matter and energy and typically gives a positive entropy change.","chem-9.1-entropy");
q("U9","9.1","Introduction to Entropy","6.B","Why does expansion of an ideal gas into a larger evacuated volume increase entropy?","The gas particles can occupy many more spatial microstates in the larger volume.",["Each gas particle gains additional protons.","The covalent bonds within the gas molecules all break.","The number of molecules necessarily doubles."],"Entropy reflects the number of accessible microstates. Expanding the available volume greatly increases the possible particle positions even if energy and number of molecules remain unchanged.","chem-9.1-entropy");
q("U9","9.2","Absolute Entropy and Entropy Change","5.C","Using standard molar entropies, how is ΔS°reaction calculated?","ΣνS°(products) − ΣνS°(reactants)",["ΣνS°(reactants) − ΣνS°(products)","the largest product entropy only","the sum of coefficients divided by temperature"],"Standard reaction entropy is a state-function difference: the stoichiometric sum of product standard entropies minus the corresponding reactant sum.","chem-9.2-absolute");
q("U9","9.2","Absolute Entropy and Entropy Change","6.C","Which substance generally has the larger standard molar entropy at the same temperature: H2O(l) or H2O(g)?","H2O(g)",["H2O(l)","They must be identical because composition is identical.","Neither has entropy because pure substances have S°=0."],"Gas-phase water has far more accessible translational microstates than liquid water, so its standard molar entropy is larger. Unlike standard enthalpy of formation for elements, absolute entropy is not defined as zero for ordinary pure substances.","chem-9.2-absolute");
q("U9","9.3","Gibbs Free Energy and Thermodynamic Favorability","5.B","At constant temperature and pressure, a process with ΔG<0 is","thermodynamically favorable in the forward direction",["necessarily instantaneous","thermodynamically unfavorable in both directions","at equilibrium regardless of composition"],"Negative Gibbs free-energy change indicates the forward change is thermodynamically favored under the specified conditions. It says nothing about how rapidly the process occurs because kinetics is separate.","chem-9.3-gibbs");
q("U9","9.3","Gibbs Free Energy and Thermodynamic Favorability","5.D","For a process with ΔH=+20 kJ mol−1 and ΔS=+100 J mol−1 K−1, above approximately what temperature does ΔG become negative?","200 K",["2 K","20 K","2000 K"],"Set ΔG=ΔH−TΔS=0. Converting 20 kJ to 20,000 J gives T=20,000/100=200 K; above this temperature the positive entropy term outweighs the positive enthalpy term.","chem-9.3-gibbs");
q("U9","9.4","Thermodynamic and Kinetic Control","6.C","A reaction has ΔG<0 but proceeds imperceptibly slowly at room temperature. Which explanation is consistent with both facts?","The reaction is thermodynamically favorable but has a large activation-energy barrier.",["A negative ΔG guarantees an extremely fast rate.","The equilibrium constant must be zero.","The reaction violates energy conservation."],"Thermodynamics determines favorability and equilibrium, whereas kinetics determines rate. A large activation barrier can make a favorable reaction extremely slow without changing the sign of ΔG.","chem-9.4-control");
q("U9","9.4","Thermodynamic and Kinetic Control","4.D","Adding a catalyst to a thermodynamically unfavorable reaction under fixed conditions will","lower activation barriers but will not make ΔG negative",["reverse the sign of ΔG","increase the equilibrium constant by changing product stability","force complete conversion to products"],"A catalyst modifies the reaction pathway and speeds forward and reverse processes. It does not change the initial and final thermodynamic states, so ΔG and K remain unchanged at the same temperature.","chem-9.4-control");
q("U9","9.5","Free Energy and Equilibrium","5.C","What relationship connects standard free energy and equilibrium constant?","ΔG°=−RT ln K",["ΔG°=RT/K","ΔG°=K/RT","ΔG°=−K ln R"],"The thermodynamic relation ΔG°=−RT ln K links the standard driving force to equilibrium composition. A large K corresponds to a negative ΔG°.","chem-9.5-freeeq");
q("U9","9.5","Free Energy and Equilibrium","6.B","If K≫1 for a reaction, what sign is expected for ΔG°?","Negative",["Positive","Always zero","Undefined because K has no logarithm"],"From ΔG°=−RT ln K, K>1 gives lnK>0 and therefore ΔG°<0. A product-favored standard equilibrium corresponds to a negative standard free-energy change.","chem-9.5-freeeq");
q("U9","9.6","Free Energy of Dissolution","5.F","For dissolution at constant temperature, the nonstandard free-energy change can be written as","ΔG=ΔG°+RT ln Q",["ΔG=ΔG°−RT/Q","ΔG=K−Q","ΔG=RT only"],"The general relation ΔG=ΔG°+RT lnQ accounts for the actual composition through the reaction quotient. It predicts the direction of spontaneous change relative to equilibrium.","chem-9.6-dissolution");
q("U9","9.6","Free Energy of Dissolution","6.C","A salt dissolution has Qsp<Ksp. What is the sign of ΔG for additional dissolution under those conditions?","Negative",["Positive","Exactly zero","Its sign cannot be related to Q and K"],"When Q<K, the forward process is thermodynamically favored until equilibrium is reached. For dissolution, that means additional dissolving has ΔG<0 under the current conditions.","chem-9.6-dissolution");
q("U9","9.7","Coupled Reactions","5.A","Reaction 1 has ΔG=+15 kJ mol−1 and reaction 2 has ΔG=−25 kJ mol−1. If coupled so their equations add, what is the net ΔG?","−10 kJ mol−1",["+10 kJ mol−1","+40 kJ mol−1","−40 kJ mol−1"],"Gibbs free-energy changes add when reaction equations are added. The coupled change is +15 + (−25) = −10 kJ mol⁻¹, so the combined process is thermodynamically favorable.","chem-9.7-coupled");
q("U9","9.7","Coupled Reactions","6.A","An unfavorable reaction can be driven by coupling it to a favorable reaction when","the sum of the two ΔG values is negative",["both individual ΔG values are positive","the catalyst makes the equilibrium constant undefined","the reactions have identical activation energies"],"Thermodynamic coupling works when the combined reaction has a negative Gibbs free-energy change. A sufficiently favorable partner can outweigh the positive ΔG of the otherwise unfavorable process.","chem-9.7-coupled");
q("U9","9.8","Galvanic (Voltaic) and Electrolytic Cells","1.B","In a galvanic cell, oxidation occurs at the","anode",["cathode","salt bridge only","voltmeter"],"Oxidation is defined as electron loss and occurs at the anode in both galvanic and electrolytic cells. In a galvanic cell, released electrons travel through the external circuit toward the cathode.","chem-9.8-cells");
q("U9","9.8","Galvanic (Voltaic) and Electrolytic Cells","4.A","What is the main function of a salt bridge in a galvanic cell?","It permits ion migration that maintains electrical neutrality in the half-cells.",["It carries electrons through solution from cathode to anode.","It supplies the activation energy for redox.","It forces both electrodes to have identical potentials."],"Electrons move through the external wire, while ions in the salt bridge migrate to prevent charge buildup in either half-cell. This ionic conduction completes the circuit and maintains near electroneutrality.","chem-9.8-cells");
q("U9","9.9","Cell Potential and Free Energy","5.C","Which equation relates standard cell potential and standard Gibbs free energy?","ΔG°=−nFE°cell",["ΔG°=nF/E°cell","ΔG°=−E°cell/nF","ΔG°=RT E°cell"],"Electrochemical work gives ΔG°=−nFE°cell, where n is moles of electrons transferred and F is Faraday's constant. A positive galvanic cell potential therefore corresponds to negative ΔG°.","chem-9.9-potential");
q("U9","9.9","Cell Potential and Free Energy","6.C","A galvanic cell has E°cell>0. Which statement follows for the cell reaction under standard conditions?","ΔG°<0 and the reaction is thermodynamically favorable.",["ΔG°>0 and the reaction is unfavorable.","ΔG°=0 regardless of E°cell.","The reaction cannot transfer electrons."],"Because ΔG°=−nFE°cell and n and F are positive, a positive standard cell potential gives a negative standard free-energy change for the reaction as written.","chem-9.9-potential");
q("U9","9.10","Cell Potential Under Nonstandard Conditions","5.F","According to the Nernst equation, increasing Q for a cell reaction at fixed temperature generally causes Ecell to","decrease",["increase","remain fixed under all conditions","become exactly equal to Q"],"The Nernst equation has the form E=E°−(RT/nF)lnQ. Increasing Q increases the subtracted logarithmic term, so the cell potential decreases.","chem-9.10-nernst");
q("U9","9.10","Cell Potential Under Nonstandard Conditions","6.B","As a galvanic cell operates and approaches equilibrium, what happens to its cell potential?","It decreases toward zero.",["It increases without limit.","It remains equal to E° regardless of concentrations.","It becomes negative before equilibrium must be reached."],"As products accumulate and reactants are consumed, Q approaches K. At equilibrium ΔG=0, and because ΔG=−nFE, the cell potential reaches zero.","chem-9.10-nernst");
q("U9","9.11","Electrolysis and Faraday’s Law","5.C","A current of 2.00 A flows for 965 s. Approximately how much charge passes through the cell?","1930 C",["483 C","967 C","193000 C"],"Electrical charge is Q=It. Multiplying 2.00 C s⁻¹ by 965 s gives 1930 C of charge delivered through the electrolytic cell.","chem-9.11-electrolysis");
q("U9","9.11","Electrolysis and Faraday’s Law","5.F","How many moles of electrons correspond to 96485 C of charge? Use F=96485 C mol−1 e−.","1.00 mol e−",["0.500 mol e−","2.00 mol e−","96485 mol e−"],"Faraday's constant is the charge per mole of electrons. Dividing 96485 C by 96485 C mol⁻¹ gives exactly 1.00 mol of electrons to the stated precision.","chem-9.11-electrolysis");

}
window.QUESTIONS_AP_CHEMISTRY = CHEM_QUESTIONS;
